r.append(R(7219034,"कैलालू (केकड़ा और पालक का सूप)","इस बेहद लोकप्रिय सूप का नाम उसकी पारंपरिक मुख्य सामग्री का भी नाम है, जो पालक जैसी एक पत्ती है। लेकिन चूँकि ब्रिटेन में कैलालू मिलना काफ़ी मुश्किल है, इसलिए इस रेसिपी में उसकी जगह पालक का इस्तेमाल किया गया है।","4","584 ग्राम",
["1 चिकन स्टॉक क्यूब, 1.2 लीटर पानी में घुला हुआ","1 छोटा प्याज़, बारीक कटा हुआ","1 लहसुन की फांक, कुचली हुई","3 हरी प्याज़ (स्प्रिंग अनियन), कटी हुई","चुटकी भर सूखा थाइम","250 ग्राम ताज़ा पालक, मोटा कटा हुआ","2 x 170 ग्राम के डिब्बे केकड़ा, छना हुआ (बराबर वज़न – लगभग 250 ग्राम ताज़ा केकड़ा)","6 बड़े चम्मच नारियल का दूध","200 ग्राम भिंडी","ताज़ी पिसी काली मिर्च","कुछ बूँदें टबैस्को"],
["स्टॉक, प्याज़, लहसुन, हरी प्याज़ और थाइम को एक बड़े पैन में डालें।","उबाल लाएँ और 10 मिनट तक हल्की आँच पर पकाएँ।","पालक, केकड़ा, नारियल का दूध और भिंडी डालें और भिंडी के नरम होने तक 10 मिनट और पकाते रहें। अच्छी तरह मसाला डालें और स्वाद अनुसार थोड़ा टबैस्को मिलाएँ।"],
["शाकाहारी संस्करण के लिए बस वेजिटेबल स्टॉक इस्तेमाल करें और एक कटी हुई लाल और पीली शिमला मिर्च तथा 400 ग्राम का एक डिब्बा राजमा डालें।",FV(1)]))
r.append(R(7220139,"भरपेट मिनेस्ट्रोन सूप","पारंपरिक इतालवी सूप का शाकाहारी संस्करण, जिसमें तुलसी और पार्मेसन चीज़ की कतरनों का स्वाद है।","6","571 ग्राम",
["1 बड़ा चम्मच तेल","2 लहसुन की फांकें, कुचली हुई","1 बड़ा प्याज़, कटा हुआ","1 बड़ी गाजर, कटी हुई","2 डंठल सेलरी, बारीक कटी हुई","450 ग्राम आटेदार आलू, कटे हुए","1.5 लीटर वेजिटेबल स्टॉक","1 x 400 ग्राम का डिब्बा कटे हुए टमाटर","125 ग्राम छोटे आकार का पास्ता","200 ग्राम फ्रेंच बीन्स, आधी कटी हुई","100 ग्राम जमे हुए मटर","एक चौथाई सैवॉय पत्तागोभी, मोटी कटी हुई","4 बड़े चम्मच ताज़ा अजमोद (पार्सले), कटा हुआ","4 बड़े चम्मच पेस्टो सॉस","ताज़ी पिसी काली मिर्च","30 ग्राम ताज़ा पार्मेसन चीज़ की कतरनें"],
["एक बड़े पैन में तेल गरम करें, लहसुन, प्याज़, गाजर, सेलरी और आलू डालें और 3-4 मिनट तक भूनें, जब तक कि वे नरम होने न लगें लेकिन भूरे न हों।","स्टॉक और टमाटर डालें, उबाल लाएँ और 10 मिनट तक हल्की आँच पर पकाएँ। पास्ता, बीन्स, मटर और पत्तागोभी डालें और 10 मिनट और पकाते रहें, या जब तक पास्ता पक न जाए।","अजमोद और पेस्टो मिलाएँ और अच्छी तरह मसाला डालें। ऊपर से पार्मेसन चीज़ की कतरनें डालकर परोसें।"],
["मिनेस्ट्रोन बची हुई सब्ज़ियों का उपयोग करने के लिए बढ़िया है, क्योंकि आप इसमें ज़्यादातर सब्ज़ियाँ डाल सकते हैं, जैसे पार्सनिप, स्वीड, आलू, तोरी, शिमला मिर्च या बैंगन।","1 छोटा चम्मच ऑरिगैनो और थोड़े चिली फ्लेक्स से स्वाद और बढ़ाएँ।","शाकाहारी पेस्टो और शाकाहारी सख़्त चीज़, जैसे तेज़ चेडर चीज़, का उपयोग करके इसे शाकाहारी बनाएँ।","फ्रीज़ करने के निर्देश: अलग-अलग भागों के लिए छोटे डिब्बों में फ्रीज़ किया जा सकता है। माइक्रोवेव में पिघलाएँ और धीरे-धीरे पूरी तरह भाप निकलने तक गरम करें।","इस पृष्ठ पर दी गई तस्वीर एक स्टॉक इमेज है, असली रेसिपी की तस्वीर नहीं।",FV(2)]))
r.append(R(7221210,"क्रिसमस पुडिंग","क्रिसमस के लिए तैयार हो जाइए, एक क्लासिक व्यंजन के हमारे ज़्यादा सेहतमंद संस्करण के साथ। फ्रिज में रखने पर यह एक हफ़्ते तक चलता है।","6","82 ग्राम",
["25 ग्राम सुल्ताना (सुनहरी किशमिश)","25 ग्राम करंट्स","25 ग्राम किशमिश","10 ग्राम मिक्स्ड पील (मिले-जुले सिट्रस छिलके)","1 बड़ा चम्मच मिक्स्ड स्पाइस","1 बड़ा चम्मच पिसी दालचीनी","आधा छोटा चम्मच पिसी लौंग","1 छोटा चम्मच पिसी अदरक (सोंठ)","तेल की 1 स्प्रे या आधा छोटा चम्मच तेल","20 ग्राम ग्लेस चेरी, कटी हुई (+ ऊपर सजाने के लिए 5 साबुत) 10 ग्राम साबुत बादाम","1 छोटा केला","1 बिना छिला सेब, कद्दूकस किया हुआ","1 छोटी गाजर, कद्दूकस की हुई","50 ग्राम बारीक ओटमील","30 ग्राम साबुत गेहूँ का आटा","आधा छोटा चम्मच बेकिंग पाउडर","1 संतरे का कद्दूकस किया हुआ ज़ेस्ट","1 नींबू का कद्दूकस किया हुआ ज़ेस्ट","10 ग्राम सूरजमुखी के बीज","10 ग्राम कद्दू के बीज"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें और केतली में पानी उबालें।","सारे सूखे मेवे और मसाले एक कटोरे में डालें, अच्छी तरह मिलाएँ और 50 मिलीलीटर उबलता पानी डालें। ढककर 15 मिनट के लिए छोड़ दें।","1 पिंट के पुडिंग बेसिन के चारों ओर तेल लगाएँ। तली में साबुत चेरी और साबुत बादाम सजाएँ।","एक अलग कटोरे में केले को मैश करें और उसमें कद्दूकस किया हुआ सेब, गाजर, ओटमील, आटा, बेकिंग पाउडर, ज़ेस्ट और बीज मिलाएँ।","मेवे, मसाले और जिस पानी में वे भीग रहे थे, उसे डालकर सब कुछ अच्छी तरह मिलाएँ। चम्मच से पुडिंग बेसिन में डालें।","चुन्नटदार ग्रीसप्रूफ़ पेपर और फ़ॉइल से ढकें और बेसिन के ऊपर कसकर लपेट दें।","बेसिन को एक गहरी ओवन ट्रे में रखें जिसमें 5 सेमी पानी हो (इसे बेन-मारी कहते हैं)। 1 घंटे तक बेक करें।","बेन-मारी से निकालें और 10 मिनट और पकाएँ। ओवन से निकालें, लेकिन ढका रहने दें। परोसने से पहले थोड़ा ठंडा होने दें।"],
["आप पुडिंग को किनारे पर डोरी बाँधकर सील करके भी पका सकते हैं। फिर बेसिन के एक तरफ़ से दूसरी तरफ़ डोरी का हैंडल बनाएँ, ताकि आप पुडिंग को बाहर निकाल सकें। कटोरे को पानी से भरे सॉसपैन में रखें जहाँ पानी कटोरे की दो-तिहाई ऊँचाई तक हो। उबाल लाएँ, ढक्कन लगाएँ और आँच कम करके 1.25 घंटे तक हल्की आँच पर पकाएँ, और ज़रूरत हो तो और उबलता पानी डालकर ध्यान रखें कि पानी भाप बनकर खत्म न हो जाए।","आप अलग-अलग सूखे मेवों की जगह मिले-जुले सूखे मेवे इस्तेमाल कर सकते हैं। अगर आपके पास सारे मसाले नहीं हैं, तो मिक्स्ड स्पाइस की मात्रा दोगुनी कर दें।","फ्रीज़ करने के निर्देश: पकाने के लिए तैयार या पके हुए, दोनों रूपों में फ्रीज़ किया जा सकता है। पिघलाएँ, फिर परोसने के लिए माइक्रोवेव में गरम करें या भाप दें।",FV(0)]))
r.append(R(7224947,"मशरूम सॉस के साथ आलू के पैनकेक","बचे हुए आलुओं का उपयोग करने के लिए बिल्कुल सही, यह सेहतमंद व्यंजन एक घंटे से भी कम समय में तैयार हो सकता है। Monika Vecerskyte द्वारा भेजा गया","3","436 ग्राम",
["6 मध्यम आकार के आलू, रगड़कर धोए हुए","2 अंडे","½ छोटा चम्मच नमक","स्वाद अनुसार आपकी पसंद की जड़ी-बूटियाँ और मसाले (हमने 1 बड़ा चम्मच ताज़ा कटा अजमोद और एक अच्छी चुटकी काली मिर्च इस्तेमाल की)","2 छोटे चम्मच तेल","2 बड़े प्याज़, कटे हुए","2 लहसुन की फांकें, कुचली हुई","250 ग्राम मशरूम, कटे हुए (कोई भी प्रकार)"],
["आलुओं को कद्दूकस करें, ढककर एक तरफ़ रख दें।","एक अलग कटोरे में अंडों को नमक और जड़ी-बूटियों तथा मसालों के साथ फेंटें। इसे कद्दूकस किए हुए आलुओं में मिलाएँ।","एक नॉन-स्टिक फ्राइंग पैन में मध्यम से धीमी आँच पर 1 छोटा चम्मच तेल डालें और आलू के मिश्रण को चम्मच से पैन में डालकर छोटे पैनकेक का आकार दें। कुछ-कुछ करके हर तरफ़ 2-3 मिनट तक पकाएँ और सारे पैनकेक पकने तक एक तरफ़ रखते जाएँ।","इस बीच, एक अलग पैन में बचा हुआ तेल डालें और प्याज़, लहसुन और मशरूम डालें। नियमित रूप से चलाते हुए 10-15 मिनट तक हल्की आँच पर पकाएँ।","जब आप आख़िरी बैच के पैनकेक पका लें, तो अलग रखे पैनकेक को 1-2 मिनट के लिए वापस पैन में डालें ताकि वे गरम हो जाएँ। मशरूम सॉस के साथ परोसें।"],
["आप 2 छोटे चम्मच करी पाउडर इस्तेमाल करके और 50 ग्राम मटर डालकर भारतीय शैली के पैनकेक बना सकते हैं और उन्हें रायते और/या आम की चटनी के साथ परोस सकते हैं।","ज़्यादा मलाईदार सॉस के लिए मशरूम में 2 बड़े चम्मच कम वसा वाला दही मिलाएँ।","प्याज़ की जगह लीक इस्तेमाल करके देखें, या 1 प्याज़ और 1 लीक इस्तेमाल करें।",FV(2)]))
r.append(R(7227794,"ब्लैकबेरी अपसाइड-डाउन पुडिंग","स्वाद से भरपूर ये पुडिंग ब्लैकबेरी का भरपूर लाभ उठाती हैं।","6","139 ग्राम",
["200 ग्राम ब्लैकबेरी","कम वसा वाले कुकिंग स्प्रे की 5 स्प्रे","60 ग्राम मुलायम पॉलीअनसैचुरेटेड स्प्रेड","60 ग्राम बारीक पिसी चीनी (कैस्टर शुगर)","2 मध्यम अंडे","120 ग्राम सफ़ेद सेल्फ़-राइज़िंग आटा","270 ग्राम कम वसा वाला रेडी-मेड कस्टर्ड, परोसने के लिए"],
["ब्लैकबेरी को 1 बड़े चम्मच पानी के साथ सॉसपैन में डालें और 2-3 मिनट तक हल्की आँच पर गरम करें। आँच से उतार लें। छह अलग-अलग पुडिंग बेसिन में कम वसा वाले कुकिंग स्प्रे से चिकनाई लगाएँ। ब्लैकबेरी के मिश्रण को उनमें बाँट दें।","स्प्रेड, कैस्टर शुगर, अंडे और आटा एक मिक्सिंग बाउल में डालें और 1 मिनट तक फेंटें, जब तक कि मिश्रण चिकना और मलाईदार न हो जाए। इसे पुडिंग बेसिन में बाँट दें और ऊपर से फ़ॉइल से ढक दें। स्टीमर में रखें और 30 मिनट तक भाप में पकाएँ, ज़रूरत हो तो उबलता पानी डालते रहें। बेसिन के किनारों पर चाकू फेरें, फिर पुडिंग को पलटकर निकाल लें। परोसने के लिए कम वसा वाला कस्टर्ड गरम करें।"],
["आप यह पुडिंग सेब या नाशपाती, या रास्पबेरी या ब्लूबेरी जैसे दूसरे फलों से भी बना सकते हैं।","अगर आपके पास स्टीमर नहीं है, तो पुडिंग को बेक कर लें। उन्हें रोस्टिंग पैन में रखें और इतना गुनगुना पानी डालें कि वह किनारों की लगभग आधी ऊँचाई तक आए, फिर 180°C/गैस 4 पर 25 मिनट तक बेक करें।","फ्रीज़ करने के निर्देश: पिघलाएँ, फिर परोसने के लिए माइक्रोवेव में गरम करें।"]))
r.append(R(7231712,"बीफ़ चॉप सुई","यह सेहतमंद चॉप सुई दुबले बीफ़ की पतली पट्टियों से बनती है, जिसे नूडल्स और ढेर सारी सब्ज़ियों के साथ स्टर-फ्राई किया जाता है।","2","555 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","200 ग्राम दुबले बीफ़ की पट्टियाँ","3 सेमी अदरक, छीला और बारीक कटा हुआ","4 लहसुन की फांकें, पतली कटी हुई","1 प्याज़, बारीक कटा हुआ","1 गाजर, माचिस की तीलियों जैसी कटी हुई","1 लाल शिमला मिर्च, पतली कटी हुई","150 ग्राम टेंडरस्टेम ब्रोकली","75 ग्राम मैंज टू (हरी मटर की फलियाँ)","125 ग्राम सूखे साबुत गेहूँ के नूडल्स","1 बड़ा चम्मच ऑयस्टर सॉस","2 छोटे चम्मच तिल"],
["कड़ाही या बड़े सॉसपैन में तेल गरम करें। बीफ़ की पट्टियाँ डालें, 1 मिनट चलाएँ, फिर अदरक और लहसुन डालें और एक मिनट और चलाएँ। बीफ़ को कड़ाही से निकालकर एक तरफ़ रख दें।","कड़ाही को वापस आँच पर रखें और प्याज़ और गाजर डालें। 2 मिनट चलाएँ, फिर लाल शिमला मिर्च और ब्रोकली डालें। 2-3 मिनट और चलाएँ।","2-3 बड़े चम्मच पानी डालें, फिर भाप को अंदर रोकने के लिए सॉसपैन के ढक्कन से ढक दें। 2 मिनट और पकाएँ।","एक सॉसपैन में पानी उबालें और सूखे नूडल्स को 4 मिनट तक पकाएँ।","बीफ़ को उसके रस के साथ वापस कड़ाही में डालें। अच्छी तरह चलाएँ। मैंज टू और छने हुए नूडल्स डालें, फिर 2 मिनट चलाएँ।","अंत में ऑयस्टर सॉस मिलाएँ और कटोरों में निकालें। परोसते समय तिल छिड़कें।"],
["ग्लूटेन-मुक्त संस्करण के लिए चावल के नूडल्स इस्तेमाल करें।","आप इस व्यंजन के लिए सूअर, चिकन या टर्की का उपयोग कर सकते हैं।","शाकाहारी संस्करण के लिए बीफ़ की जगह टोफू की पट्टियाँ इस्तेमाल करें।",FV(4)]))
r.append(R(7232073,"क्रीमी मशरूम दाल के साथ रोस्टेड कॉड","मछली को नए अंदाज़ में बनाने का तरीका, जो रात के और भरपेट खाने के लिए फ़ाइबर की मात्रा बढ़ाता है।","2","510 ग्राम",
["1 छोटा चम्मच रेपसीड तेल","1 लाल प्याज़, कटा हुआ","100 ग्राम मशरूम, फांकों में कटे हुए","1 ढेर वाला छोटा चम्मच मैदा","1 कम नमक वाला फ़िश स्टॉक क्यूब, 300 मिलीलीटर पानी में घुला हुआ","1 डिब्बा (400 ग्राम) दाल, छनी हुई","1 बड़ा चम्मच 0% वसा वाला ग्रीक दही","2 कॉड स्टेक (प्रत्येक लगभग 150 ग्राम)","1 छोटा चम्मच कटा हुआ अजमोद (पार्सले)","एक अच्छी मात्रा में पिसी काली मिर्च"],
["ओवन को 180°C/गैस 4 पर पहले से गरम करें। सॉसपैन में तेल डालें, फिर प्याज़ और मशरूम डालकर 3 मिनट पकाएँ।","मैदा समान रूप से ऊपर छिड़कें।","धीरे-धीरे स्टॉक मिलाएँ। दाल और दही डालें।","सब्ज़ी और दाल के मिश्रण को एक उथली ओवन-प्रूफ़ डिश में डालें और कॉड को ऊपर रखें।","15 मिनट तक बेक करें और अजमोद तथा ताज़ी पिसी काली मिर्च के साथ परोसें।"],
["ज़्यादातर सख़्त मछलियाँ इस व्यंजन के लिए उपयुक्त हैं – कोलि, सैल्मन या हैडॉक आज़माएँ।",FV(2)]))
r.append(R(7235332,"फ़ेटा चीज़ के साथ भुनी शिमला मिर्च","ये सेहतमंद व्यंजन सरल और स्वादिष्ट हैं।","2","255 ग्राम",
["2 शिमला मिर्च, आधी कटी और बीज निकाली हुई (1 लाल और 1 पीली या नारंगी)","12 चेरी टमाटर","8 बिना गुठली के काले जैतून","50 ग्राम फ़ेटा चीज़, चूरा किया हुआ","1 छोटा चम्मच जैतून का तेल","1 छोटा चम्मच ताज़ा ऑरिगैनो"],
["ओवन को 200°C/गैस 6 पर पहले से गरम करें। शिमला मिर्च को बेकिंग ट्रे पर कटे हुए हिस्से को ऊपर करके रखें।","बाकी सामग्री को मिलाएँ और उससे शिमला मिर्च में भरें।","30 मिनट तक पकाएँ, जब तक कि शिमला मिर्च नरम न हो जाए।"],
["आप बकरी का चीज़, पुराना चेडर या मोज़ेरेला जैसे दूसरे चीज़ भी इस्तेमाल कर सकते हैं।","इस व्यंजन के छोटे संस्करण बनाने के लिए बेबी शिमला मिर्च इस्तेमाल करके देखें (पकाने का समय घटकर 20 मिनट हो जाएगा)।",FV(2)]))
r.append(R(7237258,"चिकन और मशरूम पोटैटो बेक","एक क्लासिक बेक का नया रूप, यह रेसिपी रसीली चिकन थाई और भरपूर मशरूम को ऊपर से स्वादिष्ट नए आलुओं के साथ मिलाकर हफ़्ते के किसी भी दिन के लिए एक स्वादिष्ट भोजन तैयार करती है। इस रेसिपी को Slimming World के साथ साझेदारी में चुना गया है।","4","688 ग्राम",
["कम कैलोरी वाला कुकिंग स्प्रे","500 ग्राम बिना त्वचा और बिना हड्डी की चिकन थाई, दिखने वाली चर्बी निकाली हुई, टुकड़ों में कटी हुई","600 ग्राम मिले-जुले मशरूम, निवाले के आकार के टुकड़ों में कटे हुए","750 ग्राम नए आलू, आधे कटे हुए, या बड़े हों तो चार भागों में कटे हुए","1 प्याज़, पतला कटा हुआ","2 लहसुन की फांकें, कुचली हुई","3 समतल बड़े चम्मच कॉर्नफ़्लोर","500 मिलीलीटर कम नमक वाला चिकन स्टॉक","20 ग्राम ताज़ा फ़्लैट-लीफ़ अजमोद (पार्सले)","200 ग्राम ब्रोकली, परोसने के लिए"],
["अपने ओवन को 200°C/फ़ैन 180°C/गैस 6 पर पहले से गरम करें। एक बड़े नॉन-स्टिक फ्राइंग पैन में कुकिंग स्प्रे की दो-तीन स्प्रे करें और उसे मध्यम-तेज़ आँच पर रखें। गरम होने पर चिकन को 2-3 मिनट तक चारों तरफ़ से भूरा होने तक तलें, फिर इसे एक बड़ी ओवन-प्रूफ़ पाई या सिरेमिक बेकिंग डिश में डाल दें।","मशरूम को 5-6 मिनट तक बीच-बीच में चलाते हुए नरम होने तक तलें। उसी समय आलुओं को 8 मिनट तक उबालें, फिर पानी निकालकर एक तरफ़ रख दें। मशरूम को चिकन वाली डिश में डालें, फिर पैन में कुकिंग स्प्रे की दो-तीन स्प्रे करें और आँच मध्यम कर दें। प्याज़ को 5-6 मिनट तक तलें, फिर थोड़े पानी के साथ लहसुन डालें और 2 मिनट तक तलें।","कॉर्नफ़्लोर को कुछ चम्मच स्टॉक में मिलाकर चिकना पेस्ट बनाएँ। इसे बाकी स्टॉक में मिलाएँ और फ्राइंग पैन में डालें। उबाल लाएँ और 1-2 मिनट तक पकाएँ, जब तक कि यह गाढ़ा न हो जाए। इसे चिकन और मशरूम पर डालें, अजमोद मिलाएँ और सब कुछ एक साथ चलाएँ।","आलुओं को ऊपर दोहरी परत में सजाएँ, ताकि कुछ स्टॉक में डूब जाएँ और कुछ ऊपर रहें। कुकिंग स्प्रे की दो-तीन स्प्रे करें और 40-45 मिनट तक बेक करें, या जब तक आलू सुनहरे भूरे न हो जाएँ और स्टॉक में हल्के बुलबुले न उठने लगें। इस बीच ब्रोकली को 5-6 मिनट तक भाप में पकाएँ। बेक को ओवन से निकालें और 5 मिनट के लिए रखा रहने दें, फिर 4 कटोरों में बाँटकर परोसें।"],
["पोषण संबंधी जानकारी में परोसने का सुझाव शामिल है।",FV(2)]))
r.append(R(7238981,"मीठा विंटर चिकन","सब्ज़ियों और स्वाद से भरपूर एक स्वादिष्ट और भरपेट भोजन।","2","605 ग्राम",
["400 ग्राम मिले-जुले छिले हुए आलू, स्वीड और पार्सनिप","1 कैलोरी वाली स्प्रे","2 चिकन ब्रेस्ट","½ लाल शिमला मिर्च","½ पीली शिमला मिर्च","½ हरी शिमला मिर्च","½ प्याज़, बारीक कटा हुआ","200 मिलीलीटर कम नमक वाला वेजिटेबल स्टॉक","60 मिलीलीटर पासाटा (छनी हुई टमाटर प्यूरी)","2 बड़े चम्मच टमाटर प्यूरी","1 लहसुन की फांक, कुचली हुई","1 छोटा चम्मच मीठी स्मोक्ड पेपरिका","½ छोटा चम्मच पिसी दालचीनी","1 छोटा चम्मच वूस्टरशर सॉस","1 बड़ा चम्मच आम की चटनी","100 ग्राम शुगर स्नैप मटर या मैंज टू","3 बड़े चम्मच सेमी-स्किम्ड दूध"],
["एक पैन में पानी उबालें, आलू, स्वीड और पार्सनिप को 2 सेमी के टुकड़ों में काटें और 15-20 मिनट तक नरम होने तक हल्की आँच पर पकाएँ।","इस बीच, एक फ्राइंग पैन पर 1 कैलोरी वाली स्प्रे हल्के से करें और तेज़ आँच पर रखें। चिकन, शिमला मिर्च और प्याज़ डालें और 5 मिनट तक स्टर-फ्राई करें।","शुगर स्नैप मटर और दूध को छोड़कर बाकी सामग्री को एक साथ मिलाएँ। इसे फ्राइंग पैन में डालें, उबाल लाएँ और 10 मिनट तक हल्की आँच पर पकाएँ।","शुगर स्नैप मटर डालें। 5 मिनट और पकाएँ।","आलुओं का पानी निकाल दें। चिकना होने तक मैश करें, दूध मिलाएँ, प्लेटों में बाँटें और चिकन के साथ परोसें।"],
[FV(4)]))
r.append(R(7239635,"स्कैंडिनेवियन अचार वाले खीरे और सलाद का सैंडविच","ओपन सैंडविच एक स्वादिष्ट नाश्ता या हल्का दोपहर का भोजन बनाते हैं, जिनमें पारंपरिक सैंडविच से कम ब्रेड लगती है","4","175 ग्राम",
["175 ग्राम खीरा, बहुत पतला कटा हुआ","1 लाल प्याज़, बहुत पतला कटा हुआ","आधे नींबू का रस","2 छोटे चम्मच हॉर्सरैडिश सॉस","2 छोटे चम्मच मेयोनेज़","2 बड़े चम्मच कम वसा वाला सादा दही","4 स्लाइस (प्रत्येक स्लाइस लगभग 25 ग्राम) जर्मन शैली की गहरे रंग की साबुत अनाज वाली राई की ब्रेड","4 मुट्ठी मिले-जुले सलाद के पत्ते","100 ग्राम स्मोक्ड सैल्मन","1 छोटा चम्मच छोटे केपर्स","काली मिर्च","4 नींबू की फांकें, परोसने के लिए"],
["खीरे, लाल प्याज़ और नींबू के रस को मिलाकर एक तरफ़ रख दें।","एक छोटे कटोरे या कप में हॉर्सरैडिश, मेयोनेज़ और दही मिलाएँ।","राई की ब्रेड के हर स्लाइस पर हॉर्सरैडिश ड्रेसिंग का 1 छोटा चम्मच लगाएँ।","ब्रेड पर सलाद के पत्ते बिछाएँ, फिर सलाद के ऊपर आधा खीरा और प्याज़ बिखेरें और बाकी सॉस ऊपर से डालें।","अब थोड़े स्मोक्ड सैल्मन से सजाएँ और बचा हुआ प्याज़ और खीरा बिखेरें।","परोसने के लिए कुछ छोटे केपर्स, ताज़ी पिसी काली मिर्च और नींबू की फांकें डालें।"],
["राई की ब्रेड के कई अलग-अलग प्रकार उपलब्ध हैं, लेकिन हमेशा साबुत अनाज वाली ब्रेड चुनें।","अगर आपको स्वाद थोड़ा तेज़ लगे, तो इसके बजाय सूरजमुखी या कद्दू के बीज वाली ब्रेड आज़माएँ।","'जोखिम वाले' समूह, जैसे शिशु, बच्चे, गर्भवती महिलाएँ, बुज़ुर्ग और बीमार लोग, को खाने के लिए तैयार, कोल्ड-स्मोक्ड या क्योर की हुई मछली खाने से बचना चाहिए। इसलिए, अगर यह आप पर लागू होता है तो यह रेसिपी आपके लिए उपयुक्त नहीं है।",FV(1)]))
r.append(R(7241290,"सन-ड्राइड टमाटर ड्रेसिंग के साथ एलिचे पास्ता","घर पर बने सेहतमंद पेस्टो जैसे सॉस में लिपटा पास्ता।","3","188 ग्राम",
["225 ग्राम एलिचे पास्ता (या आपकी पसंद के आकार का पास्ता)","40 ग्राम सन-ड्राइड टमाटर और जार से 2 बड़े चम्मच तेल","1 एंकोवी फ़िलेट","1 बड़ा चम्मच केपर्स","2 बड़े चम्मच ताज़ा अजमोद (पार्सले)"],
["पास्ता को पैकेट के निर्देशों के अनुसार पकाएँ। पानी निकाल दें।","इस बीच, बाकी सारी सामग्री को ब्लेंडर या फ़ूड प्रोसेसर में डालें और 30 सेकंड तक ब्लेंड करें, जब तक कि मिल न जाए लेकिन थोड़ी बनावट बनी रहे।","सॉस को पास्ता में मिलाएँ और परोसें।"],
["आप अजमोद, तुलसी और पुदीना, या धनिया और चाइव्स जैसी ताज़ी जड़ी-बूटियों का मिश्रण इस्तेमाल कर सकते हैं।","किसी भी आकार का पास्ता चलेगा – पेन्ने, फ़ार्फ़ाले या ट्विस्ट आज़माएँ।",FV(0)]))
r.append(R(7242909,"ब्रेकफ़ास्ट बुरिटो","इन बुरिटो के साथ चलते-फिरते नाश्ता करें। आप इनमें तरह-तरह की सामग्री भर सकते हैं और बस ग्रीसप्रूफ़ पेपर में लपेट सकते हैं।","8","220 ग्राम",
["8 साबुत गेहूँ के टॉर्टिया","चिली सॉस और मसाला (वैकल्पिक)",("ठंडी फिलिंग","2 बड़े टमाटर, कटे हुए"),("ठंडी फिलिंग","1 लाल शिमला मिर्च, कटी हुई"),("ठंडी फिलिंग","4 हरी प्याज़ (स्प्रिंग अनियन), कटी हुई"),("ठंडी फिलिंग","100 ग्राम पका हुआ पालक या जमा हुआ पिघलाया हुआ, छना हुआ"),("ठंडी फिलिंग","1 एवोकाडो, छिला और कटा हुआ"),("ठंडी फिलिंग","80 ग्राम चेडर, कद्दूकस किया हुआ"),("गरम फिलिंग","1 x 400 ग्राम का डिब्बा बीन्स, छनी हुई"),("गरम फिलिंग","4 अंडों की भुर्जी")],
["ठंडी फिलिंग तैयार करें और गरम फिलिंग पकाकर गरम रखें।","टॉर्टिया को एक के ऊपर एक रखकर सूखे फ्राइंग पैन में धीमी आँच पर रखें और उन्हें नियमित रूप से पलटते रहें ताकि हर तरफ़ गरम हो जाए लेकिन सिके नहीं। टॉर्टिया के एक तरफ़ को सीधे पैन के संपर्क में गरम करें और फिर उसे ढेर के ऊपर रख दें। इसे दोहराएँ ताकि सारे टॉर्टिया गरम हो जाएँ। बाहर से कुरकुरा न करें – उन्हें मोड़ना आसान होना चाहिए, लेकिन अगर आप चाहें तो मोड़ने के बाद उन्हें कुरकुरा कर सकते हैं।","टॉर्टिया को फैलाएँ और फिर टॉर्टिया के निचले आधे हिस्से को ढकते हुए कुछ सामग्री डालें।","थोड़ा चेडर और चिली सॉस या मसाला (अगर इस्तेमाल कर रहे हैं) छिड़कें, फिर किनारों को अंदर मोड़ते हुए लपेट दें।","लपेटे हुए टॉर्टिया को सूखे फ्राइंग पैन में धीमी आँच पर जोड़ वाली तरफ़ नीचे करके रखें। दो-तीन मिनट तक पकाएँ और बराबर पकने के लिए दो-तीन बार पलटें।"],
["आप पके हुए कटे आलू, शकरकंद या मशरूम भी डाल सकते हैं।","या मांसाहारी लोग कुछ ग्रिल की हुई या स्मोक्ड मछली डाल सकते हैं।",FV(1)]))
r.append(R(7247191,"सीफ़ूड रिसोटो","क्लासिक रिसोटो का कम वसा वाला संस्करण जो फिर भी मलाईदार और लज़ीज़ है।","3","554 ग्राम",
["1 छोटा चम्मच रेपसीड तेल","1 प्याज़, बारीक कटा हुआ","1 कम नमक वाला वेजिटेबल स्टॉक क्यूब, 900 मिलीलीटर पानी में घुला हुआ","1 पीली शिमला मिर्च, बारीक कटी हुई","1 लहसुन की फांक, कुचली हुई","एक अच्छी चुटकी सफ़ेद मिर्च","15 ग्राम अजमोद (पार्सले), बारीक कटा हुआ, साथ में परोसने के लिए 1 बड़ा चम्मच","150 ग्राम आर्बोरियो (रिसोटो) चावल","1 सैल्मन स्टेक (लगभग 125 ग्राम), टुकड़ों में कटा हुआ और त्वचा निकाली हुई","100 ग्राम पके हुए छिले झींगे","50 ग्राम स्क्विड (सिक्वड) के छल्ले","50 ग्राम सादा कम वसा वाला दही","पिसी काली मिर्च","चुटकी भर ताज़ा कटा अजमोद"],
["पैन में तेल गरम करें और प्याज़ को 5 मिनट तक पकाएँ।","एक अलग पैन में स्टॉक को गरम करें, हल्की आँच पर उबलते रहने दें और बहुत धीमी आँच पर रखें।","प्याज़ में पीली शिमला मिर्च, लहसुन, सफ़ेद मिर्च और आधा अजमोद डालें, 1 मिनट चलाएँ और चावल डालें। 2 मिनट चलाएँ, फिर स्टॉक की दो कलछी डालें, इतनी कि चावल बस ढक जाएँ, और चलाएँ।","चावल को नियमित रूप से चलाते हुए, गरम स्टॉक थोड़ा-थोड़ा करके डालें, ताकि चावल बस ढके रहें। रिसोटो में बहुत हल्के बुलबुले उठते रहने चाहिए।","20 मिनट बाद, बचा हुआ स्टॉक और सैल्मन डालें। 3 मिनट और चलाएँ, झींगे और स्क्विड डालें, 2 मिनट पकाएँ, फिर चावल को चखकर देखें कि वह 'अल डेंटे' (थोड़ा सख़्त) पका है और सैल्मन अंदर तक अच्छी तरह पक गया है।","अंत में बचा हुआ अजमोद और दही ज़ोर से मिलाएँ, ढक दें और 2 मिनट रखा रहने दें। परोसने से पहले काली मिर्च और अजमोद छिड़कें।"],
["आप जमे हुए, पिघलाए हुए झींगे और स्क्विड इस्तेमाल कर सकते हैं।","स्टॉक को अलग सॉसपैन में उबलता रखें, ताकि चावल में डालते समय वह गरम रहे और तापमान न घटे जिससे चावल का पकना रुक जाए। थोड़ा-थोड़ा करके डालें; अगर खत्म हो जाए तो थोड़ा उबलता पानी डाल दें।","लकड़ी के चम्मच से नियमित रूप से चलाने पर चावल अपना स्टार्च छोड़ता है और मलाईदार बनावट सुनिश्चित होती है।",FV(1)]))
r.append(R(7247269,"फलों वाला चॉकलेट ट्रेबेक","पूरे परिवार को पसंद आने वाली यह पुडिंग गरम या ठंडी परोसी जा सकती है।","12","40 ग्राम",
["2 छोटे चम्मच रेपसीड तेल","1 बड़ा केला, चीरकर टुकड़ों में कटा हुआ (150 ग्राम)","100 ग्राम ब्लूबेरी","50 ग्राम चीनी","50 ग्राम साबुत गेहूँ का आटा","2 ढेर वाले छोटे चम्मच कोको पाउडर","1 छोटा चम्मच बेकिंग पाउडर","1 छोटा चम्मच वनीला एक्सट्रैक्ट","50 मिलीलीटर रेपसीड तेल","50 मिलीलीटर सेमी-स्किम्ड दूध (ज़रूरत हो तो और)"],
["20 x 25 सेमी के केक टिन में तेल से चिकनाई लगाएँ और ओवन को 180°C/गैस 4 पर पहले से गरम करें।","टिन की तली में केले के टुकड़े और ब्लूबेरी समान रूप से बिखेरें।","एक कटोरे में चीनी, साबुत गेहूँ का आटा, कोको पाउडर और बेकिंग पाउडर डालें और अच्छी तरह मिलाएँ।","कटोरे में वनीला एक्सट्रैक्ट, रेपसीड तेल और दूध डालें और फिर से मिलाएँ।","अगर केक का घोल बहुत गाढ़ा हो, तो धीरे-धीरे थोड़ा-थोड़ा दूध डालें जब तक कि वह चिकना और डालने लायक गाढ़ापन न पा ले।","इसे केले और ब्लूबेरी पर समान रूप से डालें और 15-20 मिनट तक बेक करें। यह तब तैयार होता है जब बीच में डाला गया चाकू साफ़ बाहर आए।"],
["आप नाशपाती, ब्लैकबेरी या रास्पबेरी जैसे किसी भी फल का मेल, या किशमिश, सुल्ताना या प्रून जैसे सूखे मेवे इस्तेमाल कर सकते हैं।","अगर आपके पास ताज़ी बेरी नहीं है, तो पिघलाए हुए जमे हुए फल भी चलेंगे, बस उनका रस निकाल दें।","ग्लूटेन-मुक्त संस्करण के लिए साबुत गेहूँ के आटे की जगह उतनी ही मात्रा (50 ग्राम) इस्तेमाल करें, आपको दूध का एक-दो बड़ा चम्मच और डालना पड़ सकता है (ग्लूटेन-मुक्त आटे गेहूँ के आटे से ज़्यादा नमी सोखते हैं) या 50 ग्राम पिसे बादाम इस्तेमाल करें और 30 ग्राम ग्लूटेन-मुक्त आटा मिलाएँ।","थोड़े क्रेम फ्रेश के साथ गरम परोसें, या केक की तरह ठंडा।","यह 23 सेमी के गोल केक टिन में भी अच्छा बनता है।"]))
save(2,r)
